import React, { useState, useMemo, useEffect } from 'react';
import { useTable, useSortBy } from 'react-table';
import { searchTracks, validateToken } from '../services/api';
import ArrowUpwardIcon from '@mui/icons-material/ArrowUpward';
import ArrowDownwardIcon from '@mui/icons-material/ArrowDownward';
import Modal from '@mui/material/Modal';
import Box from '@mui/material/Box';

const TrackSearch = ({ onTrackSelected, onReLogin }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filteredTracks, setFilteredTracks] = useState([]);
  const [selectedTrackId, setSelectedTrackId] = useState(null);
  const [authExpired, setAuthExpired] = useState(false); // Track authentication status

  // Check if the token is valid on component mount
  useEffect(() => {
    const checkAuth = async () => {
      const isValid = await validateToken();
      if (!isValid) {
        setAuthExpired(true); // Show re-login prompt
      }
    };
    checkAuth();
  }, []);

  const handleSearch = async () => {
    const isValid = await validateToken();
    if (!isValid) {
      setAuthExpired(true);
      return;
    }

    try {
      const results = await searchTracks(searchTerm);
      setFilteredTracks(results);
    } catch (error) {
      console.error('Error during search:', error);
    }
  };

  // Handle search on Enter key
  const handleKeyPress = (event) => {
    if (event.key === 'Enter') {
      handleSearch();
    }
  };

  // Define columns for react-table
  const columns = useMemo(
    () => [
      {
        Header: 'Track Name',
        accessor: 'name',
      },
      {
        Header: 'Artist Name',
        accessor: 'artists[0].name',
      },
      {
        Header: 'Album Name',
        accessor: 'album.name',
      },
      {
        Header: 'Release Date',
        accessor: 'album.release_date',
        Cell: ({ value }) => (value ? value.split('-')[0] : 'Unknown Year'),
      },
      {
        Header: 'Preview',
        accessor: 'preview_url',
        Cell: ({ value }) =>
          value ? (
            <iframe
              src={`https://open.spotify.com/embed/track/${value.split(':').pop()}`}
              width="80"
              height="80"
              frameBorder="0"
              allowTransparency="true"
              allow="encrypted-media"
            ></iframe>
          ) : (
            'No Preview Available'
          ),
      },
    ],
    []
  );

  // Prepare data for react-table
  const data = useMemo(() => filteredTracks, [filteredTracks]);

  // Initialize react-table hooks
  const { getTableProps, getTableBodyProps, headerGroups, rows, prepareRow } =
    useTable({ columns, data }, useSortBy);

  // Handle selecting a track
  const handleRowClick = (track) => {
    setSelectedTrackId(track.id);
    if (onTrackSelected) {
      onTrackSelected(track);
    }
  };

  return (
    <div>
      <input
        type="text"
        placeholder="Search for a track..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        onKeyPress={handleKeyPress} // Trigger search on Enter
      />
      <button onClick={handleSearch}>Search</button>

      {filteredTracks.length > 0 ? (
        <table {...getTableProps()} style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            {headerGroups.map((headerGroup) => {
              const { key: headerGroupKey, ...restHeaderGroupProps } = headerGroup.getHeaderGroupProps();
              return (
                <tr key={headerGroupKey} {...restHeaderGroupProps}>
                  {headerGroup.headers.map((column) => {
                    const { key: headerKey, ...restHeaderProps } = column.getHeaderProps(column.getSortByToggleProps());
                    return (
                      <th
                        key={headerKey}
                        {...restHeaderProps}
                        style={{
                          borderBottom: '1px solid black',
                          backgroundColor: '#f0f0f0',
                          cursor: 'pointer',
                          padding: '10px',
                          textAlign: 'left',
                        }}
                      >
                        {column.render('Header')}
                        <span style={{ marginLeft: '8px' }}>
                          {column.isSorted ? (
                            column.isSortedDesc ? (
                              <ArrowDownwardIcon fontSize="small" />
                            ) : (
                              <ArrowUpwardIcon fontSize="small" />
                            )
                          ) : null}
                        </span>
                      </th>
                    );
                  })}
                </tr>
              );
            })}
          </thead>
          <tbody {...getTableBodyProps()}>
            {rows.map((row) => {
              prepareRow(row);
              const { key: rowKey, ...restRowProps } = row.getRowProps();
              return (
                <tr
                  key={rowKey}
                  {...restRowProps}
                  style={{
                    cursor: 'pointer',
                    backgroundColor: row.original.id === selectedTrackId ? '#e0f7fa' : 'white',
                  }}
                  onClick={() => handleRowClick(row.original)}
                >
                  {row.cells.map((cell) => {
                    const { key: cellKey, ...restCellProps } = cell.getCellProps();
                    return (
                      <td
                        key={cellKey}
                        {...restCellProps}
                        style={{
                          padding: '10px',
                          borderBottom: '1px solid #ddd',
                        }}
                      >
                        {cell.render('Cell')}
                      </td>
                    );
                  })}
                </tr>
              );
            })}
          </tbody>
        </table>
      ) : (
        <p>No results found</p>
      )}

      {/* Modal for Re-Login */}
      <Modal
        open={authExpired}
        onClose={() => setAuthExpired(false)}
        aria-labelledby="relogin-modal"
        aria-describedby="relogin-description"
      >
        <Box
          sx={{
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            width: 300,
            bgcolor: 'background.paper',
            border: '2px solid #000',
            boxShadow: 24,
            p: 4,
          }}
        >
          <h2 id="relogin-modal">Session Expired</h2>
          <p id="relogin-description">Please re-login to continue.</p>
          <button onClick={onReLogin}>Re-Login</button>
        </Box>
      </Modal>
    </div>
  );
};

export default TrackSearch;
